//! ShIR — the language-neutral layer between the shell AST and the backends.
//!
//! `ast_to_ir` builds an `IrProgram` from the parsed shell AST using neutral
//! IR nodes (plus `sh2.*`-namespace calls expressed via `IrExpr::Call`); the
//! ESTree emitter consumes this IR via `shir_to_estree`, so the shell→ESTree
//! lowering logic lives in one place (PLAN.md §3). The Perl generator builds
//! its own IR flavor for `shir_to_perl`; the neutral nodes here
//! (Case/Redirect/Function/Subshell/Background/Arrow/...) are ESTree-path only.

use crate::ast::*;
use crate::bc::eval as bc_eval;
use crate::estree::*;
use crate::ir::*;
use std::borrow::Cow;
use std::collections::{BTreeSet, HashMap, HashSet};
use std::sync::atomic::{AtomicBool, AtomicUsize};
use std::sync::Mutex;

/// Variables proven (conservatively) to hold ONLY numbers — lifted to
/// native JS number bindings: `let x = 0` declared at program top, reads
/// become bare `x` (no `sh2.getVar` + `Number(...)||0`), writes become
/// `x = <native expr>` (no `sh2.setVar` + `arithEval`). Reset by
/// `shir_to_estree` per compilation (the Perl generator never runs this).
static LIFTED_NUMERIC: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// Provably-string variables lifted to native JS string bindings
/// (`let x = ""`; reads are bare `x`; writes `x = <string expr>`).
static LIFTED_STRING: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// C typed vars (the frontend-emitted `var_types`; set per compilation by
/// `shir_to_estree`). Consulted by the arith read coercion: Int64/UInt64
/// vars read as BigInt (Number would round past 2^53).
static VAR_TYPES: Mutex<Option<HashMap<String, IrType>>> = Mutex::new(None);
/// `--true64`: bash arithmetic is true 64-bit. Off by default (numbers
/// stay JS Numbers — silently wrong past 2^53). When on, `shir_to_estree`
/// runs `analyze_true64` and homes out-of-±2^53 numeric vars in either a
/// BigInt64Array slot (self-RMW accumulator chains — V8's native int64
/// element arithmetic, ~1.8 ns/op) or BigInt values (Int64 — exact, the
/// C-path lowering).
static TRUE64: AtomicBool = AtomicBool::new(false);
static TRUE64_SLOTS: Mutex<Option<HashMap<String, usize>>> = Mutex::new(None);
/// Out-of-±2^53 numeric vars homed as BigInt VALUES (Int64; the slots
/// win the hot RMW chains, everything else in the big regime is BigInt).
static TRUE64_INT: Mutex<Option<HashSet<String>>> = Mutex::new(None);

/// Enable/disable the `--true64` bash arithmetic lowering (default off).
pub fn set_true64(on: bool) {
    TRUE64.store(on, std::sync::atomic::Ordering::SeqCst);
}

pub fn true64_enabled() -> bool {
    TRUE64.load(std::sync::atomic::Ordering::SeqCst)
}

/// Is `name` homed in a BigInt64Array slot (the `--true64` hot-accumulator
/// lowering)?
pub fn slot_var_index(name: &str) -> Option<usize> {
    TRUE64_SLOTS
        .lock()
        .unwrap()
        .as_ref()
        .and_then(|m| m.get(name).copied())
}

/// Is `name` an out-of-±2^53 numeric var homed as BigInt values?
pub fn true64_int_var(name: &str) -> bool {
    TRUE64_INT
        .lock()
        .unwrap()
        .as_ref()
        .map(|s| s.contains(name))
        .unwrap_or(false)
}

/// `--true64` arith leaf wrapping: an ArithAst mentioning a slot var or
/// an out-of-range Int64 var must render pure BigInt arithmetic (a mixed
/// BigInt/Number binary op would throw). Num leaves become
/// `Cast(Int64, Num)` (exact `BigInt("N")`), non-slot Var leaves become
/// `Cast(Int64, Var)` (BigInt coercion); SLOT vars stay RAW (`__t64[k]`
/// — the native int64 element read keeps the RMW fast path). Applies to
/// a cloned program before the lift analyses run — and, at render time,
/// to the arith parsed out of test-string `$(( ))` operands.
pub fn arith_mentions_true64(a: &ArithAst) -> bool {
    fn mentions(a: &ArithAst) -> bool {
        match a {
            ArithAst::Var(n) => slot_var_index(n).is_some() || true64_int_var(n),
            ArithAst::Ident(n) => slot_var_index(n).is_some() || true64_int_var(n),
            ArithAst::Index { key, .. } => mentions(key),
            ArithAst::Bin { lhs, rhs, .. } => mentions(lhs) || mentions(rhs),
            ArithAst::Un { arg, .. } => mentions(arg),
            ArithAst::Cond { test, then, else_, .. } => {
                mentions(test) || mentions(then) || mentions(else_)
            }
            ArithAst::Assign { var, rhs, .. } => {
                // the TARGET matters too: `((x = 5))` on an Int64 x must
                // wrap the RHS literal (BigInt("5")) — the assignment's
                // value is the RHS, and a plain Number literal would round
                // past 2^53
                mentions(rhs) || true64_int_var(var) || slot_var_index(var).is_some()
            }
            ArithAst::IncDec { var, .. } => true64_int_var(var) || slot_var_index(var).is_some(),
            ArithAst::Sizeof(_) | ArithAst::Num(_) => false,
            ArithAst::Cast { arg, .. } => mentions(arg),
        }
    }
    mentions(a)
}

pub fn wrap_true64_arith_ast(a: &mut ArithAst) {
    fn mentions(a: &ArithAst) -> bool {
        match a {
            ArithAst::Var(n) => slot_var_index(n).is_some() || true64_int_var(n),
            ArithAst::Ident(n) => slot_var_index(n).is_some() || true64_int_var(n),
            ArithAst::Index { key, .. } => mentions(key),
            ArithAst::Bin { lhs, rhs, .. } => mentions(lhs) || mentions(rhs),
            ArithAst::Un { arg, .. } => mentions(arg),
            ArithAst::Cond { test, then, else_, .. } => {
                mentions(test) || mentions(then) || mentions(else_)
            }
            ArithAst::Assign { var, rhs, .. } => {
                // the TARGET matters too (mirror of the guard
                // `arith_mentions_true64`'s Assign arm): `((x = 5))` on an
                // Int64 x must wrap the RHS literal (BigInt("5")) — the
                // guard and the wrapper must agree or the guard fires, the
                // wrapper no-ops, and the RHS keeps its Number leaf (a
                // mixed BigInt/Number assignment throws). Core request
                // zsh-sh-go-20260814-134501.
                mentions(rhs) || true64_int_var(var) || slot_var_index(var).is_some()
            }
            ArithAst::IncDec { var, .. } => true64_int_var(var) || slot_var_index(var).is_some(),
            ArithAst::Sizeof(_) | ArithAst::Num(_) => false,
            ArithAst::Cast { arg, .. } => mentions(arg),
        }
    }
    fn wrap(a: &mut ArithAst) {
        match a {
            ArithAst::Num(_) => {
                *a = ArithAst::Cast {
                    ty: IrType::Int64,
                    arg: Box::new(std::mem::replace(a, ArithAst::Num(0))),
                };
            }
            ArithAst::Var(n) => {
                if slot_var_index(n).is_none() {
                    *a = ArithAst::Cast {
                        ty: IrType::Int64,
                        arg: Box::new(std::mem::replace(a, ArithAst::Num(0))),
                    };
                }
            }
            // an Ident read is a lifted binding — the same BigInt wrap as
            // a non-slot Var (the A1 export only emits Ident for lifted
            // vars, and a lifted var is never slot-homed).
            ArithAst::Ident(n) => {
                if slot_var_index(n).is_none() {
                    *a = ArithAst::Cast {
                        ty: IrType::Int64,
                        arg: Box::new(std::mem::replace(a, ArithAst::Num(0))),
                    };
                }
            }
            ArithAst::Sizeof(_) => {
                *a = ArithAst::Cast {
                    ty: IrType::Int64,
                    arg: Box::new(std::mem::replace(a, ArithAst::Num(0))),
                };
            }
            ArithAst::Index { key, .. } => wrap(key),
            ArithAst::Bin { lhs, rhs, .. } => {
                wrap(lhs);
                wrap(rhs);
            }
            ArithAst::Un { arg, .. } => wrap(arg),
            ArithAst::Cond { test, then, else_, .. } => {
                wrap(test);
                wrap(then);
                wrap(else_);
            }
            ArithAst::Assign { rhs, .. } => wrap(rhs),
            ArithAst::Cast { arg, .. } => wrap(arg),
            ArithAst::IncDec { .. } => {}
        }
    }
    if mentions(a) {
        wrap(a);
    }
}

/// The program-level wrapper: apply [`wrap_true64_arith_ast`] to every
/// Arith expr in the program.
pub fn wrap_true64_arith(prog: &mut IrProgram) {
    fn walk_stmts(stmts: &mut [IrStmt]) {
        for s in stmts {
            match s {
                IrStmt::Assign { expr, .. } => {
                    if let IrExpr::Arith(a) = expr {
                        wrap_true64_arith_ast(a);
                    }
                }
                IrStmt::Expr(e) => {
                    if let IrExpr::Arith(a) = e {
                        wrap_true64_arith_ast(a);
                    }
                }
                IrStmt::If {
                    then,
                    elsifs,
                    else_,
                    ..
                } => {
                    walk_stmts(then);
                    for (_, arm) in elsifs {
                        walk_stmts(arm);
                    }
                    walk_stmts(else_);
                }
                IrStmt::While { body, .. }
                | IrStmt::For { body, .. }
                | IrStmt::DoWhile { body, .. }
                | IrStmt::Block(body)
                | IrStmt::Subshell(body)
                | IrStmt::Background(body) => walk_stmts(body),
                IrStmt::Redirect { inner, .. } => walk_stmts(inner),
                IrStmt::Function { body, .. } => walk_stmts(body),
                IrStmt::Try {
                    body,
                    excepts,
                    else_body,
                    finally_body,
                } => {
                    walk_stmts(body);
                    for e in excepts.iter_mut() {
                        if let Some(IrExpr::Arith(a)) = &mut e.match_expr {
                            wrap_true64_arith_ast(a);
                        }
                        walk_stmts(&mut e.body);
                    }
                    walk_stmts(else_body);
                    walk_stmts(finally_body);
                }
                _ => {}
            }
        }
    }
    walk_stmts(&mut prog.stmts);
}
/// Names with NO write anywhere in the current program (set per
/// compilation by `shir_to_estree`; see [`collect_never_written`]). A
/// read of such a name lowers to a constant `""` under the documented
/// SH2_ASSUME_NO_ENV assumption (default ON — see
/// [`never_written_read`]): bash would read the name from the parent
/// environment, which the assumption declares unobservable. Special
/// names (`?`/`$`/`#`/`@`/`*`/`0`-`9`/`-`/`PWD`/`HOSTNAME`/... —
/// [`native_special_var`]'s set) and the env-resident denylist
/// ([`ENV_RESIDENT_NAMES`]) never fold.
static NEVER_WRITTEN: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// Names whose EVERY write in the program is an ARRAY write (set per
/// compilation by `shir_to_estree`; see [`collect_array_only_written`]).
/// The plain-name `${arr:off:len}` slice lowering (SH2_ASSUME_ARRAY_SLICE)
/// consults it: a name in this set is either unset or an array at every
/// read, so the runtime's array-vs-scalar dispatch is unobservable and
/// the array branch lowers natively.
static ARRAY_ONLY_NAMES: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// Names the emitter may access DIRECTLY on the runtime's plain-object
/// store (`sh2.vars.<name>` — a property read/write, no getVar/setVar
/// dispatch; see [`collect_native_store_access`]). Set per compilation
/// by `shir_to_estree`.
static NATIVE_STORE_READ_BLOCKED: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// The WRITE-side blocker set: the runtime setVar's attribute branches
/// (`typeset -i/-l/-u`, namerefs, exported/PATH env sync) exclude the
/// name from native writes (see [`collect_native_store_access`]).
static NATIVE_STORE_WRITE_BLOCKED: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// Names with a REAL (non-arith-text) assignment source (set per
/// compilation by `shir_to_estree`; see [`collect_arith_ref_set_vars`]).
/// The `$(( $var ... ))` dollar-ref arith lowering ([`native_arith_text`])
/// consults it: a provably-set var reads as a plain decimal under
/// SH2_ASSUME_ARITH_VARS; a var with NO other source may be UNSET at the
/// read, and bash's EMPTY text substitution must then still parse (the
/// deletion gate) or the runtime evaluator stays.
static ARITH_REF_SET: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// The "No spaces" tag verdicts (see `analyze_var_nospace`): the set of
/// vars whose value is PROVABLY free of IFS whitespace. Set per
/// compilation by `shir_to_estree`; the `split` call emitter consults it
/// to skip the word-split on such vars (a provable no-op).
static VAR_NOSPACE: Mutex<Option<HashSet<String>>> = Mutex::new(None);
/// Whether the program may run with a CUSTOM (non-whitespace) IFS value
/// in the store (frontends-ifs: `IFS=,` assignments / `setVar("IFS", …)`
/// / env-carrying `IFS=…` exec calls, with a value not provably
/// whitespace-only). Set per compilation by `shir_to_estree`; when set,
/// the "No spaces" tag is DISABLED (a whitespace-free value may still
/// contain custom separator chars) and the `split` marker must dispatch
/// to the runtime (`sh2.split`, which consults `this.vars.IFS`) instead
/// of the inline whitespace regex.
static IFS_CUSTOM: Mutex<Option<bool>> = Mutex::new(None);
/// Whether `shopt -s nocasematch` may be enabled anywhere in the current
/// program (set per compilation by `shir_to_estree`; see
/// `ir_may_enable_nocasematch`). Native case/test substring lifts must
/// lowercase to stay exact when it is.
static CASE_NOCASE: Mutex<Option<bool>> = Mutex::new(None);
/// Whether the program contains BOTH `shopt -s` and `shopt -u
/// nocasematch` (set per compilation by `shir_to_estree`; see
/// `ir_nocase_state_dynamic`): the runtime state can change mid-program,
/// so static case-folds must fall back to the runtime test/caseMatch
/// calls, which consult `shoptState` dynamically.
static CASE_NOCASE_DYNAMIC: Mutex<Option<bool>> = Mutex::new(None);
/// Nesting depth of `sh2.and`/`sh2.or` arrow lowering (see the BinOp And/Or
/// arms). The runtime helpers branch on `lastExit`, which a NATIVE test
/// expression never sets — so inside `&&`/`||` arrows a test must stay a
/// runtime `sh2.test` call (which records the status) and only the
/// value-consuming positions (if/while/until conds, `!`, ternary) get the
/// native lowering.
static AND_OR_DEPTH: Mutex<usize> = Mutex::new(0);
/// Native arith div/mod poison depth: >0 while lowering a `$((...))`
/// expression that contains a NaN-COERCING operator (bitwise `|`/`&`/`^`/
/// shifts, `**`, comparisons, `&&`/`||`, `!`, ternaries — JS converts NaN
/// to 0/false/true where bash would abort the WHOLE expansion). A zero
/// divisor in such an expression must keep the runtime `idiv`/`imod`
/// THROW (the only mechanism that aborts mid-expression); poison-free
/// expressions (div/mod results only flow through `+ - * / %` and unary
/// +/- into the arithEval boundary) can go fully native — NaN reaches
/// the wrapper and converts to the bash empty result.
static ARITH_POISON_DEPTH: Mutex<usize> = Mutex::new(0);
/// The render-time i53/`--true64` leaf-wrap depth (see
/// [`arith_to_estree_wrapped`]): 0 = the top-level call, which owns the
/// mention-wrap; nested calls skip it (the tree is already wrapped).
static ARITH_WRAP_DEPTH: Mutex<usize> = Mutex::new(0);
/// Native-echo emission depth: >0 while lowering inside a construct whose
/// runtime stdout sink differs from the module's stdout — `redirect` /
/// `pipeline` / `capture` / `captureWords` calls (the runtime swaps
/// fdTargets) — or inside a function body (a script function may be
/// CALLED under any sink at runtime; the emitter cannot see the call
/// site's context). `process.stdout.write` is only byte-identical to the
/// runtime's `emit` when fd 1 is the default stdout, so the native echo
/// lowering (see `try_native_echo`) checks this depth before firing.
static ECHO_SINK_DEPTH: Mutex<usize> = Mutex::new(0);
/// Plan 4 test-status elision depth: >0 while lowering a `[ ]`-test
/// whose lastExit write is provably unread (a bare `[ ]` statement or a
/// dead if/while condition — see [`compute_test_cond_deadness`] and the
/// `test` statement/cond emission): the test arm emits the bare boolean
/// (`try_native_test_unstatused`) instead of the
/// `(sh2._g = t, sh2.lastExit = …, sh2._g)` status protocol. Only the
/// value-consuming positions (statement/if/while cond at AND_OR_DEPTH
/// 0) raise it; `&&`/`||` chains keep the statused form (the links
/// branch on lastExit).
static TEST_UNSTATUSED_DEPTH: Mutex<usize> = Mutex::new(0);
/// Subshell/background statement sites whose body provably runs with the
/// DEFAULT stdout sink (see [`native_echo_sink_sites`]): their arrows
/// lower WITHOUT the sink-depth bump (the `arrow_native_echo` form), so
/// echo/printf/pwd statements directly in the body fire the native
/// `process.stdout.write` lowering. Pointer-keyed on the body stmts
/// slice; set per compilation by `shir_to_estree`; unset → conservative
/// (every subshell/background keeps the runtime dispatch — the
/// pre-existing behavior).
static NATIVE_ECHO_SINK_SITES: Mutex<Option<HashSet<usize>>> = Mutex::new(None);
fn native_echo_sink_site(stmts: &[IrStmt]) -> bool {
    NATIVE_ECHO_SINK_SITES
        .lock()
        .unwrap()
        .as_ref()
        .map(|s| s.contains(&(stmts.as_ptr() as usize)))
        .unwrap_or(false)
}
/// Does a redirect spec list touch fd 1 (the echo sink)? Only fd-1 specs
/// change where a body's stdout writes land: fd-0 input redirects
/// (`cmd < f`, heredocs, herestrings, procsubs — the `while ... done < f`
/// read-loop family) and fd-2-only redirects leave fd 1 untouched, so the
/// body's echo/printf/pwd can still lower to native `process.stdout.write`
/// (the runtime's redirectSync/redirect still installs and restores the
/// other fds around the body — the fd-1 writes are the only ones the
/// native lowering replaces). `2>&1`-style dups read fd 1's target but do
/// not change it; `exec >f`-persist forms carry an fd-1 spec and are
/// covered (PROGRAM_PERSIST_FD1 additionally disables native echo
/// program-wide for them).
fn redirect_specs_touch_fd1(specs: &[(i64, &str, &IrExpr)]) -> bool {
    specs.iter().any(|(fd, _, _)| *fd == 1)
}
/// `redirect` CALL form (expr position): parse the specs array for an
/// fd-1 object. Any malformed spec is treated as touching fd 1
/// (conservative — the depth bump stays).
fn redirect_call_touches_fd1(args: &[IrExpr]) -> bool {
    let [_, IrExpr::Array(spec_objs)] = args else {
        return true;
    };
    spec_objs.iter().any(|so| match so {
        IrExpr::Object(props) => props
            .iter()
            .any(|(k, v)| k == "fd" && matches!(v, IrExpr::Int(1))),
        _ => true,
    })
}
/// Whether every redirect spec is an fd-dup (`&N` target) — the ONLY
/// targets the runtime's sync `redirectSync` twin accepts. File paths,
/// heredocs/herestrings and dynamic targets need the async fs bridge, so
/// a redirect carrying any of them must stay on the async `redirect`
/// path (the sync twin would throw "redirection needs the async
/// redirect bridge" at runtime).
///
/// (2026-08-14 audit — ELIGIBILITY WIDENED to ALL targets: the runtime's
/// `redirectSync` shares `_applyRedirectSpecs` with the async `redirect`
/// and every mode it handles is synchronous — fd-dups are fd-table
/// operations, heredocs/herestrings are in-memory string targets,
/// `r`-mode does `fs.existsSync`, `w`/`a`-mode does the eager
/// `openSync`/`closeSync` check, body writes go through the sync
/// `writeFileSync` emitter and `readFileSync` reader, and dynamic
/// targets resolve via the sync `expandWord`. The "async fs bridge"
/// throw this function's original comment described never existed in
/// sh2-namespace.mjs (verified against the full git history). The only
/// remaining async reason is an AWAIT in the lowered body or specs —
/// which the callers already check separately (expr_has_await).)
fn redirect_specs_sync_ok(_specs: &[(i64, &str, &IrExpr)]) -> bool {
    true
}

/// The expr-position `redirect` CALL form: the same verdict over the
/// spec OBJECTS (see [`redirect_specs_sync_ok`]).
fn redirect_call_sync_ok(_args: &[IrExpr]) -> bool {
    true
}
/// Whether the program contains a PERSISTENT fd-1 redirect (a bare
/// `exec >file` / `exec 1>&2` / `exec 1>&-` — the runtime keeps those in
/// the fd table after the redirect call). Native top-level `echo` writes
/// `process.stdout` directly, which is only byte-identical while fd 1 is
/// the module's default stdout — a persistent fd-1 redirect ANYWHERE in
/// the program (functions included; the emitter cannot see call-site
/// contexts) disables the native echo lowering. Set per compilation by
/// `shir_to_estree`; conservative (any doubt resolves to `true`). (a bare
/// `exec >file` / `exec 1>&2` / `exec 1>&-` — the runtime keeps those in
/// the fd table after the redirect call). Native top-level `echo` writes
/// `process.stdout` directly, which is only byte-identical while fd 1 is
/// the module's default stdout — a persistent fd-1 redirect ANYWHERE in
/// the program (functions included; the emitter cannot see call-site
/// contexts) disables the native echo lowering. Set per compilation by
/// `shir_to_estree`; conservative (any doubt resolves to `true`).
static PROGRAM_PERSIST_FD1: Mutex<Option<bool>> = Mutex::new(None);
/// Per-function `local`-variable native lift: function name → the set of
/// local vars whose declarations (and every later reference) lower to
/// native `let` bindings inside the function body (see
/// `local_lift_analysis`). Set per compilation by `shir_to_estree`.
static LOCAL_LIFT: Mutex<Option<HashMap<String, HashSet<String>>>> = Mutex::new(None);
/// Function-definition scope stack during emission: each frame is
/// (function name, the local-decl names already emitted in this body —
/// first decl is a `let`, later ones are assignments).
static FUNCTION_STACK: Mutex<Vec<(String, HashSet<String>)>> = Mutex::new(Vec::new());
/// Whether the program may enable `set -e` (errexit) anywhere (set per
/// compilation by `shir_to_estree`; see `ir_may_enable_errexit`). The
/// runtime's `sh2.guard` wrapper is an identity function when the errexit
/// flag never turns on, so guard emission is skipped entirely for programs
/// that provably never enable it.
static MAY_ERREXIT: Mutex<Option<bool>> = Mutex::new(None);
/// LastExit-write liveness (Plan 4): per-statement "the `sh2.lastExit`
/// write this statement performs is DEAD (no read observes it before the
/// next write / the block's status consumer)" flags, keyed by statement
/// pointer (stable between the pre-pass and emission — the IR tree is
/// immutable there, and the *Sync loop lowering emits the ORIGINAL body
/// references, never clones). Set per compilation by `shir_to_estree` via
/// [`compute_lastexit_deadness`]; the `(( ))` statement lowering drops the
/// status ternary + lastExit writes when a statement's write is dead (keep
/// the side effect). Unset → conservative.
static LASTEXIT_DEAD: Mutex<Option<HashMap<usize, bool>>> = Mutex::new(None);
/// The FUNCTION-BODY deadness during the define-arrow construction: the
/// function body is CLONED into the arrow (`IrExpr::Arrow(body.clone())`
/// in the Function arm), so the global map's pointer keys (computed on
/// the ORIGINAL tree) never match the clone. The Function arm computes
/// the clone's deadness into this static for the duration of the arrow
/// construction (the clone's statements are alive then — their pointer
/// keys cannot collide) and restores the previous value after (no stale
/// keys for a later allocation's reuse). Only function bodies: loop /
/// subshell / capture arrows are built from the ORIGINAL body references
/// (never cloned), so the global map covers them.
static ARROW_BODY_DEAD: Mutex<Option<HashMap<usize, bool>>> = Mutex::new(None);
fn lastexit_write_is_dead(stmt: &IrStmt) -> bool {
    // The active function-arrow construction's map wins (its pointers are
    // the exact statements being emitted); fall back to the global map
    // (original-tree pointers — loops/subshells/redirects).
    if let Some(m) = ARROW_BODY_DEAD.lock().unwrap().as_ref() {
        if let Some(&dead) = m.get(&(stmt as *const IrStmt as usize)) {
            return dead;
        }
    }
    LASTEXIT_DEAD
        .lock()
        .unwrap()
        .as_ref()
        .map(|m| {
            m.get(&(stmt as *const IrStmt as usize))
                .copied()
                .unwrap_or(false)
        })
        .unwrap_or(false)
}

/// Plan 4 extension: `test`-CONDITION deadness — per If/While statement,
/// the `[ ]` condition's status write (the `(sh2._g = t, sh2.lastExit =
/// …, sh2._g)` seq) is provably unread, so the emitter drops the status
/// protocol and emits the bare boolean condition. Keyed by statement
/// pointer like [`LASTEXIT_DEAD`]; computed in
/// [`compute_lastexit_deadness`] (which owns the live set). Unset →
/// conservative (statused).
static TEST_COND_DEAD: Mutex<Option<HashMap<usize, bool>>> = Mutex::new(None);
/// The function-arrow twin of [`TEST_COND_DEAD`] (same clone-pointer gap
/// as [`ARROW_BODY_DEAD`] — the clone's if/while conditions' `_g` status
/// protocol is dropped only when the clone's own liveness says the write
/// is unread). Active only during the define-arrow construction.
static ARROW_BODY_COND_DEAD: Mutex<Option<HashMap<usize, bool>>> = Mutex::new(None);
fn test_cond_write_is_dead(stmt: &IrStmt) -> bool {
    if let Some(m) = ARROW_BODY_COND_DEAD.lock().unwrap().as_ref() {
        if let Some(dead) = m.get(&(stmt as *const IrStmt as usize)) {
            return *dead;
        }
    }
    TEST_COND_DEAD
        .lock()
        .unwrap()
        .as_ref()
        .map(|m| {
            m.get(&(stmt as *const IrStmt as usize))
                .copied()
                .unwrap_or(false)
        })
        .unwrap_or(false)
}

/// For-loop statements that must PERSIST the loop variable's final value
/// into its native binding after the loop (see [`analyze_loop_var_refs`]):
/// the loop var is LIFTED and referenced OUTSIDE its loop body, and the
/// loop sits OUTSIDE a copy region (subshell/background/capture — bash
/// writes there are copy-local, so the module binding must not be
/// clobbered; those loops keep the shadowed binding and their vars stay
/// store-bound instead). Keyed by statement pointer (stable between the
/// analysis and emission — the IR tree is immutable there). Unset →
/// conservative (no persist).
static LOOP_PERSIST: Mutex<Option<HashMap<usize, ()>>> = Mutex::new(None);
fn loop_persist_needed(stmt: &IrStmt, var: &str) -> bool {
    LOOP_PERSIST
        .lock()
        .unwrap()
        .as_ref()
        .map(|m| m.contains_key(&(stmt as *const IrStmt as usize)) && is_lifted(var))
        .unwrap_or(false)
}

/// Plan 4 lastExit-write liveness (see [`compute_lastexit_deadness`]).
/// `ir_stmt_writes_lastexit` is the WRITER predicate: every runtime call
/// records its own status to lastExit — EXCEPT the pure writers that
/// return true WITHOUT touching it (`setVar`/`setArray`/`shopt`/`define`;
/// `break`/`continue`/`return` leave it untouched — they are IrStmt::Expr
/// control signals, and the runtime's `return`/`break` helpers are only
/// reached through fnCall dispatch). An over-approximated writer would
/// shadow a LIVE write and break `$?`, so the set is exactly the runtime
/// truth.
pub(crate) fn ir_stmt_writes_lastexit(stmt: &IrStmt) -> bool {
    match stmt {
        IrStmt::Exec {
            cmd,
            redirects,
            env,
            ..
        } => {
            if !redirects.is_empty() || !env.is_empty() {
                return true; // the runtime dispatch records its own status
            }
            match cmd {
                IrExpr::Str(name, _) => {
                    !matches!(name.as_str(), "setVar" | "setArray" | "shopt" | "define")
                }
                _ => true,
            }
        }
        // loops/subshells/redirects/if/pipeline leave a final status
        // (the loop runtime writes `bodyLastExit`; an if's status is its
        // run arm's final write; a redirect's status is its inner's).
        IrStmt::While { .. }
        | IrStmt::DoWhile { .. }
        | IrStmt::For { .. }
        | IrStmt::If { .. }
        | IrStmt::Subshell(_)
        | IrStmt::Background(_)
        | IrStmt::Block(_)
        | IrStmt::Redirect { .. }
        | IrStmt::Pipeline { .. } => true,
        // `setVar`-style expression statements (never lastExit writers)
        IrStmt::Expr(IrExpr::Call { func, .. }) => !matches!(
            func.as_str(),
            "setVar" | "setArray" | "shopt" | "define" | "break" | "continue" | "return"
        ),
        // `((i++))` — the arith_forms Assign(Arith(IncDec)) shape writes
        // the `(( ))` status (the value's nonzeroness) in its lowering
        IrStmt::Assign { expr, .. } => matches!(expr, IrExpr::Arith(a)
            if matches!(&**a, ArithAst::IncDec { .. })),
        _ => false,
    }
}

/// Does an expression observe the PREVIOUS exit status? `$?` lowers to
/// `IrExpr::Var("?")` (a `sh2.lastExit` read); a `$?` inside an arith
/// string stays the literal text (the runtime evalArith reads the status).
/// Over-approximated (single-quoted literal "$?" text included) — a
/// spurious reader only keeps a write live (safe).
pub(crate) fn ir_expr_reads_status(e: &IrExpr) -> bool {
    match e {
        IrExpr::Var(name, _) => name == "?",
        IrExpr::Str(s, _) => s.contains("$?"),
        IrExpr::Index { key, .. } => ir_expr_reads_status(key),
        IrExpr::BinOp { lhs, rhs, .. } => ir_expr_reads_status(lhs) || ir_expr_reads_status(rhs),
        IrExpr::Call { func, args } => {
            // `$?` at word level lowers to `sh2.getVar("?")` (the runtime
            // special-cases it to lastExit) — the Var("?") form appears
            // on the lifted/native path
            args.iter().any(ir_expr_reads_status)
                || (func == "getVar" && matches!(args.as_slice(), [IrExpr::Str(n, _)] if n == "?"))
        }
        IrExpr::MethodCall { obj, args, .. } => {
            ir_expr_reads_status(obj) || args.iter().any(ir_expr_reads_status)
        }
        IrExpr::Ternary {
            cond, then, else_, ..
        } => {
            ir_expr_reads_status(cond) || ir_expr_reads_status(then) || ir_expr_reads_status(else_)
        }
        IrExpr::DefinedOr { expr, default } => {
            ir_expr_reads_status(expr) || ir_expr_reads_status(default)
        }
        IrExpr::Interpolate(parts) => parts.iter().any(|p| match p {
            InterpPart::Lit(s) => s.contains("$?"),
            InterpPart::Expr(e) => ir_expr_reads_status(e),
        }),
        // a command substitution inherits `$?` (bash runs it in a
        // subshell) — the wrapped command may read the status
        IrExpr::Capture { expr, .. } => ir_expr_reads_status(expr),
        IrExpr::Array(items) => items.iter().any(ir_expr_reads_status),
        // numeric literal range `start..end` — never a status read
        IrExpr::Range { .. } => false,
        IrExpr::Arrow(stmts) => ir_stmts_read_status(stmts),
        _ => false,
    }
}

pub(crate) fn ir_stmts_read_status(stmts: &[IrStmt]) -> bool {
    stmts.iter().any(ir_stmt_reads_status)
}

/// Does a STATEMENT observe the previous exit status (so a write before it
/// is live)? Readers: `and`/`or` (branch on the previous status), native
/// `&&`/`||` (the `sh2.lastExit === 0` test), `exit`/`return` with no arg
/// (carry the previous status), every `$?` expansion, and — transitively —
/// a subshell/function/background body whose first actions may read the
/// inherited status. Over-approximated: a spurious reader keeps a write
/// live (safe); a MISSED reader would drop a live write (never).
pub(crate) fn ir_stmt_reads_status(stmt: &IrStmt) -> bool {
    match stmt {
        IrStmt::Exec { cmd, args, .. } => {
            if args.iter().any(ir_expr_reads_status) || ir_expr_reads_status(cmd) {
                return true;
            }
            matches!(cmd, IrExpr::Str(name, _) if matches!(name.as_str(), "and" | "or" | "exit" | "return"))
        }
        IrStmt::Expr(e) => match e {
            IrExpr::BinOp { op, .. } => matches!(op, BinOpKind::And | BinOpKind::Or),
            IrExpr::Call { func, args } => {
                args.iter().any(ir_expr_reads_status)
                    || matches!(func.as_str(), "and" | "or" | "exit" | "return")
            }
            other => ir_expr_reads_status(other),
        },
        IrStmt::While { cond, .. } | IrStmt::If { cond, .. } => ir_expr_reads_status(cond),
        IrStmt::DoWhile { cond, .. } => ir_expr_reads_status(cond),
        IrStmt::For { iter, .. } => ir_expr_reads_status(iter),
        IrStmt::Assign { expr, .. } => ir_expr_reads_status(expr),
        IrStmt::Declare { init, .. } => init.as_ref().map(ir_expr_reads_status).unwrap_or(false),
        IrStmt::Output { value, .. } => ir_expr_reads_status(value),
        IrStmt::WriteFile { path, content, .. } => {
            ir_expr_reads_status(path) || ir_expr_reads_status(content)
        }
        IrStmt::Return(opt) => opt.as_ref().map(ir_expr_reads_status).unwrap_or(true),
        IrStmt::Exit(opt) => opt.as_ref().map(ir_expr_reads_status).unwrap_or(true),
        // subshell/background bodies may read the inherited status
        IrStmt::Subshell(body) | IrStmt::Background(body) => ir_stmts_read_status(body),
        IrStmt::Function {
            body,
            named_blocks,
            ..
        } => {
            // named blocks run inside the function (begin/process/end
            // wrappers) — their $? reads keep writers alive too
            ir_stmts_read_status(body)
                || named_blocks
                    .iter()
                    .any(|(_, b)| ir_stmts_read_status(b))
        }
        IrStmt::Redirect { inner, redirects } => {
            ir_stmts_read_status(inner)
                || redirects.iter().any(|r| match r {
                    IrRedirect { fd: _, target, .. } => ir_expr_reads_status(target),
                })
        }
        _ => false,
    }
}

/// The statement-level `(( ))` / `let ARITH...` that lowers via
/// [`try_native_let`] — the ONLY droppable lastExit writer (the status
/// ternary exists solely to record lastExit + the boolean value). Matches
/// both statement carriers (the general `IrStmt::Expr(Call("exec", …))`
/// form and the `IrStmt::Exec` form).
fn is_native_let_stmt(stmt: &IrStmt) -> bool {
    match stmt {
        IrStmt::Expr(IrExpr::Call { func, args, .. }) => {
            func == "exec"
                && matches!(args.as_slice(), [IrExpr::Str(n, _), IrExpr::Array(_)] if n == "let")
        }
        IrStmt::Exec { cmd, args, .. } => {
            matches!(cmd, IrExpr::Str(n, _) if n == "let")
                && matches!(args.as_slice(), [IrExpr::Str(n2, _), IrExpr::Array(_)] if n2 == "let")
        }
        // `((i++))` — the arith_forms transform's Assign(Arith(IncDec))
        // shape (mirror of the `let "i++"` exec): same status semantics,
        // same deadness treatment (the hot loop's bare `++i`).
        IrStmt::Assign { targets, expr, .. } => {
            matches!(expr, IrExpr::Arith(a)
                if matches!(&**a, ArithAst::IncDec { var, .. }
                    if targets.len() == 1 && targets[0].indices.is_empty()
                        && &targets[0].var == var))
        }
        _ => false,
    }
}

/// Plan 4 — backward block scan: a statement's lastExit write is LIVE iff
/// a reader (or the block's status consumer) observes it before the next
/// writer. `end_live`: does the BLOCK's consumer read the block's final
/// status? (loop runtime reads `this.lastExit` after the body; the program
/// runner's final status; if-arm flows to the if's own liveness...)
pub(crate) fn scan_lastexit_liveness(stmts: &[IrStmt], end_live: bool, live: &mut HashSet<usize>) {
    let mut read_pending = end_live;
    for stmt in stmts.iter().rev() {
        if ir_stmt_writes_lastexit(stmt) {
            if read_pending {
                live.insert(stmt as *const IrStmt as usize);
                read_pending = false;
            }
            // else: shadowed — dead (unless a reader between the write
            // and the next writer observed it — handled above)
        }
        if ir_stmt_reads_status(stmt) {
            read_pending = true;
        }
    }
}

pub(crate) fn walk_lastexit_liveness(stmts: &[IrStmt], end_live: bool, live: &mut HashSet<usize>) {
    scan_lastexit_liveness(stmts, end_live, live);
    for stmt in stmts {
        let self_live = live.contains(&(stmt as *const IrStmt as usize));
        match stmt {
            IrStmt::While { body, .. } | IrStmt::For { body, .. } | IrStmt::Block(body) => {
                walk_lastexit_liveness(body, self_live, live);
            }
            IrStmt::DoWhile { body, .. } => walk_lastexit_liveness(body, self_live, live),
            IrStmt::If {
                then,
                elsifs,
                else_,
                ..
            } => {
                walk_lastexit_liveness(then, self_live, live);
                for (_, arm) in elsifs {
                    walk_lastexit_liveness(arm, self_live, live);
                }
                walk_lastexit_liveness(else_, self_live, live);
            }
            IrStmt::Subshell(body) | IrStmt::Background(body) => {
                walk_lastexit_liveness(body, self_live, live);
            }
            IrStmt::Redirect { inner, .. } => walk_lastexit_liveness(inner, self_live, live),
            // A called function's status is recorded by fnCall — live iff
            // the callee's final status may be observed (see fn_end_live:
            // program observers anywhere, or a final-position call).
            // Unobserved callees walk dead (their tracking writes drop).
            // Named blocks run inside the function.
            IrStmt::Function {
                name,
                body,
                named_blocks,
                ..
            } => {
                let end_live = fn_end_live(name);
                walk_lastexit_liveness(body, end_live, live);
                for (_, nb) in named_blocks {
                    walk_lastexit_liveness(nb, end_live, live);
                }
            }
            _ => {}
        }
    }
}

/// Per-function lastExit end-liveness: the call-site refinement to the
/// historically always-live function walk above. `name -> end_live` for
/// the functions DEFINED in this compilation; absent means live (the
/// status quo ante). Set per compilation in `shir_to_estree` (before
/// `compute_lastexit_deadness`, whose walk reads it); cleared in
/// `transforms::apply` so a previous compilation's map never leaks into a
/// transform-phase walk (e.g. test_lowering's). Unset (transform phase,
/// disabled gate) → every function live, bit-identical to the old
/// unconditional walk.
static FN_END_LIVE: Mutex<Option<HashMap<String, bool>>> = Mutex::new(None);
pub(crate) fn clear_fn_end_live() {
    *FN_END_LIVE.lock().unwrap() = None;
}
fn fn_end_live(name: &str) -> bool {
    FN_END_LIVE
        .lock()
        .unwrap()
        .as_ref()
        .and_then(|m| m.get(name).copied())
        .unwrap_or(true)
}

/// Compute the per-function end-live map for a compilation: `end_live(f)`
/// is true iff f's final status may be observed. Observation channels:
/// (a) any status observer program-wide (then every defined function
/// stays live — the old behavior; refining to per-function readers is
/// future work), else (b) final-called functions (their final status IS
/// the program's exit code, possibly through capture/assignment chains).
/// Gated by the `lastexit-call-sites` transform flag (empty/unset gate =
/// on, like every registry transform); disabled → empty map → every
/// function live (status quo ante, for bisection).
///
/// This is the generic shIR-level analysis every backend shares: the walk
/// above feeds LASTEXIT_DEAD / TEST_COND_DEAD / LOOP_STATUS_DEAD, which
/// the renderers consult. Backends without status tracking (C has none;
/// Python's While is a bare native loop) need no hook; backends that add
/// tracking later read the same verdicts. Out-of-crate backends can use
/// the serialized `"runs"` markup precedent if they ever need it.
pub(crate) fn compute_fn_end_live(prog: &IrProgram) -> HashMap<String, bool> {
    if !crate::transforms::transform_enabled("lastexit-call-sites") {
        return HashMap::new();
    }
    let mut defined: HashMap<String, Vec<IrStmt>> = HashMap::new();
    let mut ambiguous: HashSet<String> = HashSet::new();
    collect_defined_functions(&prog.stmts, &mut defined, &mut ambiguous);
    // A sub sharing a shell function's name makes calls ambiguous — the
    // outparam channel is invisible to the call recognition below, so
    // force live (conservative; the status quo ante for that name).
    for sub in &prog.subs {
        if defined.contains_key(&sub.name) {
            ambiguous.insert(sub.name.clone());
        }
    }
    if prog_status_observed(prog, &defined) {
        return HashMap::new();
    }
    let final_called = final_called_functions(&prog.stmts, &defined);
    defined
        .keys()
        .map(|n| {
            (
                n.clone(),
                ambiguous.contains(n) || final_called.contains(n),
            )
        })
        .collect()
}

/// Shell function names defined anywhere (nested defs included) with
/// their bodies. Redefinitions go to `ambiguous` (callers may target
/// either body — always live). Sub bodies are NOT collected (the liveness
/// walk never visits them; their tracking is unconditionally kept) — but
/// a sub colliding with a shell name forces ambiguity (see above).
fn collect_defined_functions(
    stmts: &[IrStmt],
    defined: &mut HashMap<String, Vec<IrStmt>>,
    ambiguous: &mut HashSet<String>,
) {
    for st in stmts {
        match st {
            IrStmt::Function { name, body, .. } => {
                if defined.contains_key(name) {
                    ambiguous.insert(name.clone());
                } else {
                    defined.insert(name.clone(), body.clone());
                }
                collect_defined_functions(body, defined, ambiguous);
            }
            IrStmt::While { body, .. }
            | IrStmt::For { body, .. }
            | IrStmt::Block(body)
            | IrStmt::DoWhile { body, .. }
            | IrStmt::Subshell(body)
            | IrStmt::Background(body) => {
                collect_defined_functions(body, defined, ambiguous)
            }
            IrStmt::ForInit { init, body, step, .. } => {
                collect_defined_functions(init, defined, ambiguous);
                collect_defined_functions(body, defined, ambiguous);
                collect_defined_functions(step, defined, ambiguous);
            }
            IrStmt::If {
                then,
                elsifs,
                else_,
                ..
            } => {
                collect_defined_functions(then, defined, ambiguous);
                for (_, b) in elsifs {
                    collect_defined_functions(b, defined, ambiguous);
                }
                collect_defined_functions(else_, defined, ambiguous);
            }
            IrStmt::Redirect { inner, .. } => {
                collect_defined_functions(inner, defined, ambiguous)
            }
            IrStmt::Case { clauses, .. } => {
                for c in clauses {
                    collect_defined_functions(&c.body, defined, ambiguous);
                }
            }
            IrStmt::Pipeline { stages, .. } => {
                for s in stages {
                    collect_defined_functions(s, defined, ambiguous);
                }
            }
            // Try/Select/Ext/Asm bodies are never visited by the liveness
            // walk (conservative status quo there) — nothing to collect.
            _ => {}
        }
    }
}

/// True iff any status observer exists anywhere: top-level statements,
/// function bodies at any depth, named blocks, and sub bodies. The shared
/// reader predicate covers and/or-chains, bare exit/return, and every $?
/// expansion (transitively through subshells, captures and bodies); the
/// extra scan below covers the forms it does not model. Subs are included
/// for observers (a nested chain there still consumes a status) but never
/// for defined/final-called (their end status is outparam-channeled).
/// Over-approximating here only keeps tracking (safe); missing an
/// observer would drop a live write (never).
fn prog_status_observed(
    prog: &IrProgram,
    defined: &HashMap<String, Vec<IrStmt>>,
) -> bool {
    if ir_stmts_read_status(&prog.stmts) {
        return true;
    }
    if prog
        .subs
        .iter()
        .any(|s| ir_stmts_read_status(&s.body))
    {
        return true;
    }
    if prog
        .stmts
        .iter()
        .any(|s| stmt_has_extra_observer(s, defined))
    {
        return true;
    }
    prog.subs.iter().any(|s| {
        s.body
            .iter()
            .any(|st| stmt_has_extra_observer(st, defined))
    })
}

/// Command names whose mere presence forces conservative all-live
/// functions: `wait` (reaps a background job's status — `f & wait` as
/// program-final exits with f's status), `eval`/`source`/`.` (dynamic
/// code may do anything). `command`/`time` are NOT observers — their
/// target is recognized transparently by the call scan below (`command
/// -v` probing costs nothing; over-recording a probe is safe).
fn extra_observer_cmd(name: &str) -> bool {
    matches!(name, "wait" | "eval" | "source" | ".")
}

/// Statement forms with unverified status behavior — observers by fiat
/// (rare nodes; keeping status quo there is free). Anything the analyzer
/// below does not explicitly recurse into or classify is also an
/// observer; new IrStmt variants MUST be classified here (no wildcard —
/// the compiler enforces it).
fn stmt_has_extra_observer(stmt: &IrStmt, defined: &HashMap<String, Vec<IrStmt>>) -> bool {
    match stmt {
        IrStmt::Exec { cmd, args, .. } => {
            if let IrExpr::Str(name, _) = cmd {
                if extra_observer_cmd(name) {
                    return true;
                }
            }
            args.iter()
                .any(|a| expr_has_extra_observer(a, defined, false))
        }
        IrStmt::Expr(e) => expr_has_extra_observer(e, defined, false),
        IrStmt::Assign { expr, .. } => expr_has_extra_observer(expr, defined, false),
        IrStmt::Declare { init, .. } => init
            .as_ref()
            .map(|e| expr_has_extra_observer(e, defined, false))
            .unwrap_or(false),
        IrStmt::DeclareArray { elements, .. } => elements
            .iter()
            .any(|e| expr_has_extra_observer(e, defined, false)),
        IrStmt::Output { value, .. } => expr_has_extra_observer(value, defined, false),
        IrStmt::WriteFile { path, content, .. } => {
            // Unverified status behavior (redirect-write node) — observer.
            let _ = (path, content);
            true
        }
        IrStmt::Return(opt) | IrStmt::Exit(opt) => opt
            .as_ref()
            .map(|e| expr_has_extra_observer(e, defined, false))
            .unwrap_or(false),
        IrStmt::SetChildError(_) => true,
        IrStmt::Require(_) | IrStmt::RawText(_) => true,
        IrStmt::Warn { .. } => true,
        IrStmt::Die { .. } => false,
        IrStmt::Break | IrStmt::Continue | IrStmt::Label(_) | IrStmt::Goto(_) => {
            // Labels/gotos defeat structured final-position reasoning
            // (a backward jump re-enters past writers) — observer.
            matches!(stmt, IrStmt::Label(_) | IrStmt::Goto(_))
        }
        IrStmt::While { cond, body } | IrStmt::DoWhile { body, cond, .. } => {
            cond_calls_observe(cond, defined)
                || body.iter().any(|s| stmt_has_extra_observer(s, defined))
        }
        IrStmt::If {
            cond,
            then,
            elsifs,
            else_,
            ..
        } => {
            cond_calls_observe(cond, defined)
                || then.iter().any(|s| stmt_has_extra_observer(s, defined))
                || elsifs.iter().any(|(_, b)| {
                    b.iter().any(|s| stmt_has_extra_observer(s, defined))
                })
                || else_.iter().any(|s| stmt_has_extra_observer(s, defined))
        }
        IrStmt::For { iter, body, .. } => {
            expr_has_extra_observer(iter, defined, false)
                || body.iter().any(|s| stmt_has_extra_observer(s, defined))
        }
        IrStmt::ForInit {
            init,
            cond,
            step,
            body,
        } => {
            // A C-style cond can call (`for (i=0; f(); i++)`) — the call
            // consumes f's status into the loop machinery.
            cond_calls_observe(cond, defined)
                || init.iter().any(|s| stmt_has_extra_observer(s, defined))
                || expr_has_extra_observer(cond, defined, false)
                || step.iter().any(|s| stmt_has_extra_observer(s, defined))
                || body.iter().any(|s| stmt_has_extra_observer(s, defined))
        }
        IrStmt::Case { discriminant, clauses } => {
            expr_has_extra_observer(discriminant, defined, false)
                || clauses.iter().any(|c| {
                    c.body.iter().any(|s| stmt_has_extra_observer(s, defined))
                })
        }
        IrStmt::Pipeline { stages, .. } => stages
            .iter()
            .any(|s| s.iter().any(|st| stmt_has_extra_observer(st, defined))),
        IrStmt::Redirect { inner, redirects } => {
            inner.iter().any(|s| stmt_has_extra_observer(s, defined))
                || redirects.iter().any(|r| expr_has_extra_observer(&r.target, defined, false))
        }
        IrStmt::Function { body, named_blocks, .. } => {
            body.iter().any(|s| stmt_has_extra_observer(s, defined))
                || named_blocks.iter().any(|(_, b)| {
                    b.iter().any(|s| stmt_has_extra_observer(s, defined))
                })
        }
        IrStmt::Subshell(body) | IrStmt::Background(body) | IrStmt::Block(body) => body
            .iter()
            .any(|s| stmt_has_extra_observer(s, defined)),
        // try/select/ext/asm: unknown status flow — observer (status quo).
        IrStmt::Try { .. } | IrStmt::Select { .. } | IrStmt::Ext(_) | IrStmt::Asm { .. } => true,
    }
}

/// A user-function call directly in a loop/if condition (`if f`, `while
/// f`): the dispatch consumes f's final status — a stale never-ran value
/// would mis-branch. External commands need nothing (the runtime sets
/// their own status); value positions never reach here (callers pass
/// in_cond=false for args and captures).
fn cond_calls_observe(cond: &IrExpr, defined: &HashMap<String, Vec<IrStmt>>) -> bool {
    match cond {
        IrExpr::Call { func, args }
            if matches!(
                func.as_str(),
                "exec" | "builtin" | "fnCall" | "$fn_call" | "command" | "time"
            ) =>
        {
            args.iter().any(|a| matches!(a, IrExpr::Str(n, _) if defined.contains_key(n)))
        }
        _ => expr_has_extra_observer(cond, defined, false),
    }
}

/// Extra observers inside expressions. `in_cond` is true only at the top
/// of a condition (see above) — every nested command argument, capture
/// and value resets it (shadowed or value-consumed there). Any &&/||/!
/// anywhere consumes a status (nested chains are not statement-level
/// readers); any PIPESTATUS text may read the pipe status array.
fn expr_has_extra_observer(
    e: &IrExpr,
    defined: &HashMap<String, Vec<IrStmt>>,
    in_cond: bool,
) -> bool {
    match e {
        IrExpr::BinOp { op, lhs, rhs } => {
            matches!(
                op,
                crate::ir::BinOpKind::And
                    | crate::ir::BinOpKind::Or
                    | crate::ir::BinOpKind::Not
            ) || expr_has_extra_observer(lhs, defined, false)
                || expr_has_extra_observer(rhs, defined, false)
        }
        IrExpr::Call { func, args } => {
            if matches!(func.as_str(), "wait" | "eval" | "source" | ".") {
                return true;
            }
            // The general `exec`/`builtin` carrier names its command in
            // args[0] (far more common than IrStmt::Exec) — `wait` reaps
            // background statuses wherever it appears.
            if matches!(func.as_str(), "exec" | "builtin")
                && matches!(args.first(), Some(IrExpr::Str(n, _)) if extra_observer_cmd(n))
            {
                return true;
            }
            if func == "and" || func == "or" {
                // Frontend-emitted chain calls (the `and`/`or` reader
                // family) — nested ones are not statement readers.
                return true;
            }
            if in_cond
                && matches!(
                    func.as_str(),
                    "exec" | "builtin" | "fnCall" | "$fn_call" | "command" | "time"
                )
                && args
                    .iter()
                    .any(|a| matches!(a, IrExpr::Str(n, _) if defined.contains_key(n)))
            {
                return true;
            }
            args.iter()
                .any(|a| expr_has_extra_observer(a, defined, false))
        }
        IrExpr::Str(s, _) => s.contains("PIPESTATUS"),
        IrExpr::Var(name, _) => name == "?",
        IrExpr::Ident(name) => name == "?",
        IrExpr::Arith(a) => arith_reads_status(a),
        IrExpr::Index { key, .. } => expr_has_extra_observer(key, defined, false),
        IrExpr::MethodCall { obj, args, .. } => {
            expr_has_extra_observer(obj, defined, false)
                || args
                    .iter()
                    .any(|a| expr_has_extra_observer(a, defined, false))
        }
        IrExpr::Ternary { cond, then, else_ } => {
            expr_has_extra_observer(cond, defined, false)
                || expr_has_extra_observer(then, defined, false)
                || expr_has_extra_observer(else_, defined, false)
        }
        IrExpr::DefinedOr { expr, default } => {
            expr_has_extra_observer(expr, defined, false)
                || expr_has_extra_observer(default, defined, false)
        }
        IrExpr::Interpolate(parts) => parts.iter().any(|p| match p {
            crate::ir::InterpPart::Lit(s) => s.contains("PIPESTATUS"),
            crate::ir::InterpPart::Expr(x) => expr_has_extra_observer(x, defined, false),
        }),
        IrExpr::Capture { expr, .. } => expr_has_extra_observer(expr, defined, false),
        IrExpr::Splice(inner) => expr_has_extra_observer(inner, defined, false),
        // Backend-specific expression opaqueness — unknown status
        // behavior, so an observer (status quo wherever one appears).
        IrExpr::Ext(_) => true,
        IrExpr::Arrow(stmts) => stmts
            .iter()
            .any(|s| stmt_has_extra_observer(s, defined)),
        IrExpr::Array(items) => items
            .iter()
            .any(|a| expr_has_extra_observer(a, defined, false)),
        IrExpr::ArrayComp { .. } => {
            // Comprehension internals unexamined — observer (rare node).
            true
        }
        IrExpr::Lambda { body, .. } => body
            .iter()
            .any(|s| stmt_has_extra_observer(s, defined)),
        IrExpr::Object(fields) => fields
            .iter()
            .any(|(_, v)| expr_has_extra_observer(v, defined, false)),
        // Data, never status: numbers, bools, ranges, identifiers (other
        // than `?` above), regex patterns (not expansions), raw backend
        // bridges (the emitter refuses them before status matters).
        IrExpr::Int(_)
        | IrExpr::Bool(_)
        | IrExpr::Range { .. }
        | IrExpr::Ident(_)
        | IrExpr::Regex { .. }
        | IrExpr::RawExpr(_)
        | IrExpr::Json(_) => false,
    }
}

/// `$?` inside an arithmetic tree (a frontend-emitted `Arith(Var("?"))`
/// — the shell parser rejects `$` in arith text, so the core parser never
/// produces this; the shared reader predicate has no Arith arm either).
fn arith_reads_status(a: &ArithAst) -> bool {
    match a {
        ArithAst::Var(n) | ArithAst::Ident(n) => n == "?",
        ArithAst::Index { key, .. } => arith_reads_status(key),
        ArithAst::Bin { lhs, rhs, .. } => arith_reads_status(lhs) || arith_reads_status(rhs),
        ArithAst::Un { arg, .. } => arith_reads_status(arg),
        ArithAst::Cond { test, then, else_, .. } => {
            arith_reads_status(test) || arith_reads_status(then) || arith_reads_status(else_)
        }
        ArithAst::Assign { rhs, .. } => arith_reads_status(rhs),
        ArithAst::IncDec { .. } | ArithAst::Num(_) => false,
        ArithAst::Sizeof(_) => false,
        ArithAst::Cast { arg, .. } => arith_reads_status(arg),
    }
}

/// Functions whose final status can BE the program's exit code: invoked in
/// final command position. Only the LAST statement of a block can
/// determine its final status (earlier calls are shadowed by a later
/// writer, or the last statement determines 0 itself) — so the descent
/// follows last statements through the status-transparent forms (blocks,
/// subshells, redirect inners, if/case arms, pipeline last stages,
/// capture-taking assignments) and records direct calls, stopping
/// everywhere else. Over-approximating (recording a mere string mention
/// or a value-position capture) only keeps tracking — safe; missing a
/// flow would drop a live write — never (each STOP below was audited:
/// builtins overwrite, tests overwrite, loops synthesize via the dance
/// the existing self_live walk already protects).
///
/// The result feeds `fn_end_live` (with a fixpoint through recorded
/// bodies: a final-called function's own final calls determine its end
/// status, which is what its callers observe).
fn final_called_functions(
    top: &[IrStmt],
    defined: &HashMap<String, Vec<IrStmt>>,
) -> HashSet<String> {
    let mut out = HashSet::new();
    mark_final_calls(top, defined, &mut out);
    // Fixpoint through recorded bodies.
    let mut stack: Vec<String> = out.iter().cloned().collect();
    while let Some(name) = stack.pop() {
        if let Some(body) = defined.get(&name) {
            let prev: HashSet<String> = out.clone();
            mark_final_calls(body, defined, &mut out);
            for n in out.difference(&prev) {
                stack.push(n.clone());
            }
        }
    }
    out
    }

fn mark_final_calls(
    stmts: &[IrStmt],
    defined: &HashMap<String, Vec<IrStmt>>,
    out: &mut HashSet<String>,
) {
    let Some(last) = stmts.last() else {
        return;
    };
    match last {
        // Transparent forwards: the inside-final determines the status.
        IrStmt::Block(b) | IrStmt::Subshell(b) => mark_final_calls(b, defined, out),
        IrStmt::Redirect { inner, .. } => mark_final_calls(inner, defined, out),
        IrStmt::If {
            then,
            elsifs,
            else_,
            ..
        } => {
            mark_final_calls(then, defined, out);
            for (_, b) in elsifs {
                mark_final_calls(b, defined, out);
            }
            mark_final_calls(else_, defined, out);
        }
        IrStmt::Case { clauses, .. } => {
            for c in clauses {
                mark_final_calls(&c.body, defined, out);
            }
        }
        IrStmt::Pipeline { stages, .. } => {
            if let Some(last_stage) = stages.last() {
                mark_final_calls(last_stage, defined, out);
            }
        }
        // Loops synthesize via the tracking dance (never-ran 0) — bodies
        // do not determine the exit directly; the existing self_live walk
        // already protects them.
        IrStmt::While { .. }
        | IrStmt::DoWhile { .. }
        | IrStmt::For { .. }
        | IrStmt::ForInit { .. } => {}
        // Assignments take a capture RHS's status (`x=$(f)` exits with
        // f's status); plain values determine 0.
        IrStmt::Assign { expr, .. } => mark_flow_expr(expr, defined, out),
        IrStmt::Declare { init: Some(e), .. } => mark_flow_expr(e, defined, out),
        IrStmt::DeclareArray { elements, .. } => {
            for e in elements {
                mark_flow_expr(e, defined, out);
            }
        }
        // A bare capture/command expression in final position.
        IrStmt::Expr(e) => mark_flow_expr(e, defined, out),
        // Direct and indirect calls determine the status via the callee;
        // `command`/`time`/`exec`/`builtin` wrappers are transparent, so
        // their Str args are scanned uniformly (a `command -v` probe that
        // merely mentions a name over-records — safe).
        IrStmt::Exec { cmd, args, .. } => {
            record_cmd_strs(cmd, args, defined, out);
        }
        // Definitions, signals and builtins determine their own status;
        // nested captures inside their args are shadowed (overwritten).
        // (WriteFile/Declare-plain determine 0 in bash; any runtime
        // preservation gap there is pre-existing and untouched — the
        // top-level walk is bit-identical with the gate off.)
        _ => {}
    }
}

/// Record defined-function names from a command and its direct Str args
/// (uniform over-approximation — see above; a mere string mention only
/// keeps tracking).
fn record_cmd_strs(
    cmd: &IrExpr,
    args: &[IrExpr],
    defined: &HashMap<String, Vec<IrStmt>>,
    out: &mut HashSet<String>,
) {
    if let IrExpr::Str(name, _) = cmd {
        if defined.contains_key(name) {
            out.insert(name.clone());
        }
    }
    for a in args {
        if let IrExpr::Str(name, _) = a {
            if defined.contains_key(name) {
                out.insert(name.clone());
            }
        }
    }
}

/// Record user-function calls whose end status can flow to the program's
/// exit code through this expression: direct command Calls, Captures
/// (forwarded) and Arrow bodies (subshell command contexts in flow
/// position). Chain operands record everything in their subtree
/// (defensive: the extras scan already falls back on any nested chain,
/// so this arm never decides alone — belt and braces, zero coupling).
/// Value wrappers (arrays, interpolation, ternaries, compares) are
/// descended uniformly — over-approximating a value-position capture
/// only keeps tracking. Unknown call funcs record their whole subtree
/// (a forwarding semantic we have not audited must never be missed).
fn mark_flow_expr(
    e: &IrExpr,
    defined: &HashMap<String, Vec<IrStmt>>,
    out: &mut HashSet<String>,
) {
    match e {
        IrExpr::Capture { expr, .. } => mark_flow_expr(expr, defined, out),
        IrExpr::Splice(inner) => mark_flow_expr(inner, defined, out),
        IrExpr::Ext(ext) => {
            for c in ext.children() {
                mark_flow_expr(c, defined, out);
            }
        }
        IrExpr::Arrow(stmts) => mark_final_calls(stmts, defined, out),
        IrExpr::Call { func, args } => {
            if matches!(
                func.as_str(),
                "exec" | "builtin" | "fnCall" | "$fn_call" | "command" | "time"
            ) {
                record_cmd_strs(
                    args.first().unwrap_or(&IrExpr::Bool(false)),
                    args,
                    defined,
                    out,
                );
                for a in args {
                    if let IrExpr::Arrow(stmts) = a {
                        mark_final_calls(stmts, defined, out);
                    }
                }
            } else {
                // Unknown (or value) call: record the whole subtree — a
                // forwarding semantic we have not audited must never be
                // missed. Test/arith/getVar shapes over-record here;
                // harmless (keeps tracking) and rare in flow position.
                record_all_calls_in_expr(e, defined, out);
            }
        }
        IrExpr::Array(items) => {
            for i in items {
                mark_flow_expr(i, defined, out);
            }
        }
        IrExpr::Interpolate(parts) => {
            for p in parts {
                if let crate::ir::InterpPart::Expr(x) = p {
                    mark_flow_expr(x, defined, out);
                }
            }
        }
        IrExpr::Ternary { cond, then, else_ } => {
            mark_flow_expr(cond, defined, out);
            mark_flow_expr(then, defined, out);
            mark_flow_expr(else_, defined, out);
        }
        IrExpr::DefinedOr { expr, default } => {
            mark_flow_expr(expr, defined, out);
            mark_flow_expr(default, defined, out);
        }
        IrExpr::BinOp { op, lhs, rhs } => {
            if matches!(
                op,
                crate::ir::BinOpKind::And
                    | crate::ir::BinOpKind::Or
                    | crate::ir::BinOpKind::Not
            ) {
                record_all_calls_in_expr(e, defined, out);
            } else {
                mark_flow_expr(lhs, defined, out);
                mark_flow_expr(rhs, defined, out);
            }
        }
        IrExpr::Index { key, .. } => mark_flow_expr(key, defined, out),
        IrExpr::MethodCall { obj, args, .. } => {
            mark_flow_expr(obj, defined, out);
            for a in args {
                mark_flow_expr(a, defined, out);
            }
        }
        // Leaves and value-only forms: a variable or literal is not a
        // call (Arith trees hold no calls by construction), and object
        // values do not determine status.
        IrExpr::Int(_)
        | IrExpr::Str(..)
        | IrExpr::Var(..)
        | IrExpr::Ident(_)
        | IrExpr::Bool(_)
        | IrExpr::Arith(_)
        | IrExpr::Regex { .. }
        | IrExpr::Range { .. }
        | IrExpr::RawExpr(_)
        | IrExpr::Json(_) => {}
        IrExpr::Object(fields) => {
            for (_, v) in fields {
                mark_flow_expr(v, defined, out);
            }
        }
        IrExpr::ArrayComp { .. } => {
            // Unexamined comprehension internals — record defensively.
            record_all_calls_in_expr(e, defined, out);
        }
        IrExpr::Lambda { .. } => {
            // Invocation-invisible body: its calls cannot determine the
            // program exit (status consumers inside still trip the
            // extras scan, which recurses lambda bodies).
        }
    }
}

/// Defensive over-approximation: every direct-Str user-function name
/// anywhere in the subtree counts as called. Safe (keeps tracking).
fn record_all_calls_in_expr(
    e: &IrExpr,
    defined: &HashMap<String, Vec<IrStmt>>,
    out: &mut HashSet<String>,
) {
    match e {
        IrExpr::Str(name, _) => {
            if defined.contains_key(name) {
                out.insert(name.clone());
            }
        }
        IrExpr::Call { args, .. } => {
            for a in args {
                record_all_calls_in_expr(a, defined, out);
            }
        }
        IrExpr::Array(items) => {
            for a in items {
                record_all_calls_in_expr(a, defined, out);
            }
        }
        IrExpr::BinOp { lhs, rhs, .. }
        | IrExpr::DefinedOr { expr: lhs, default: rhs } => {
            record_all_calls_in_expr(lhs, defined, out);
            record_all_calls_in_expr(rhs, defined, out);
        }
        IrExpr::Ternary { cond, then, else_ } => {
            record_all_calls_in_expr(cond, defined, out);
            record_all_calls_in_expr(then, defined, out);
            record_all_calls_in_expr(else_, defined, out);
        }
        IrExpr::Interpolate(parts) => {
            for p in parts {
                if let crate::ir::InterpPart::Expr(x) = p {
                    record_all_calls_in_expr(x, defined, out);
                }
            }
        }
        IrExpr::Capture { expr, .. } => record_all_calls_in_expr(expr, defined, out),
        IrExpr::Splice(inner) => record_all_calls_in_expr(inner, defined, out),
        IrExpr::Ext(ext) => {
            for c in ext.children() {
                record_all_calls_in_expr(c, defined, out);
            }
        }
        IrExpr::Arrow(stmts) => {
            for s in stmts {
                record_all_calls_in_stmt(s, defined, out);
            }
        }
        IrExpr::Index { key, .. } => record_all_calls_in_expr(key, defined, out),
        IrExpr::MethodCall { obj, args, .. } => {
            record_all_calls_in_expr(obj, defined, out);
            for a in args {
                record_all_calls_in_expr(a, defined, out);
            }
        }
        IrExpr::Object(fields) => {
            for (_, v) in fields {
                record_all_calls_in_expr(v, defined, out);
            }
        }
        _ => {}
    }
}

/// Statement-level half of the defensive scan above: records every
/// command-looking call anywhere in the subtree (all bodies, all
/// expressions). Deliberately exhaustive over composites — an unvisited
/// corner would silently under-record.
fn record_all_calls_in_stmt(
    stmt: &IrStmt,
    defined: &HashMap<String, Vec<IrStmt>>,
    out: &mut HashSet<String>,
) {
    match stmt {
        IrStmt::Exec { cmd, args, .. } => {
            record_cmd_strs(cmd, args, defined, out);
            for a in args {
                record_all_calls_in_expr(a, defined, out);
            }
        }
        IrStmt::Expr(e)
        | IrStmt::Assign { expr: e, .. }
        | IrStmt::Output { value: e, .. }
        | IrStmt::SetChildError(e) => {
            record_all_calls_in_expr(e, defined, out);
        }
        IrStmt::Declare { init, .. } => {
            if let Some(e) = init {
                record_all_calls_in_expr(e, defined, out);
            }
        }
        IrStmt::DeclareArray { elements, .. } => {
            for e in elements {
                record_all_calls_in_expr(e, defined, out);
            }
        }
        IrStmt::WriteFile { path, content, .. } => {
            record_all_calls_in_expr(path, defined, out);
            record_all_calls_in_expr(content, defined, out);
        }
        IrStmt::Return(opt) | IrStmt::Exit(opt) => {
            if let Some(e) = opt {
                record_all_calls_in_expr(e, defined, out);
            }
        }
        IrStmt::While { cond, body } | IrStmt::DoWhile { body, cond, .. } => {
            record_all_calls_in_expr(cond, defined, out);
            for b in body {
                record_all_calls_in_stmt(b, defined, out);
            }
        }
        IrStmt::If {
            cond,
            then,
            elsifs,
            else_,
            ..
        } => {
            record_all_calls_in_expr(cond, defined, out);
            for b in then.iter().chain(else_) {
                record_all_calls_in_stmt(b, defined, out);
            }
            for (_, b) in elsifs {
                for stm in b {
                    record_all_calls_in_stmt(stm, defined, out);
                }
            }
        }
        IrStmt::For { iter, body, .. } => {
            record_all_calls_in_expr(iter, defined, out);
            for b in body {
                record_all_calls_in_stmt(b, defined, out);
            }
        }
        IrStmt::ForInit {
            init,
            cond,
            step,
            body,
        } => {
            for b in init.iter().chain(body).chain(step) {
                record_all_calls_in_stmt(b, defined, out);
            }
            record_all_calls_in_expr(cond, defined, out);
        }
        IrStmt::Case { discriminant, clauses } => {
            record_all_calls_in_expr(discriminant, defined, out);
            for c in clauses {
                for b in &c.body {
                    record_all_calls_in_stmt(b, defined, out);
                }
            }
        }
        IrStmt::Pipeline { stages, .. } => {
            for s in stages {
                for b in s {
                    record_all_calls_in_stmt(b, defined, out);
                }
            }
        }
        IrStmt::Redirect { inner, redirects } => {
            for b in inner {
                record_all_calls_in_stmt(b, defined, out);
            }
            for r in redirects {
                record_all_calls_in_expr(&r.target, defined, out);
            }
        }
        IrStmt::Function {
            body,
            named_blocks,
            ..
        } => {
            for b in body {
                record_all_calls_in_stmt(b, defined, out);
            }
            for (_, nb) in named_blocks {
                for b in nb {
                    record_all_calls_in_stmt(b, defined, out);
                }
            }
        }
        IrStmt::Block(body) | IrStmt::Subshell(body) | IrStmt::Background(body) => {
            for b in body {
                record_all_calls_in_stmt(b, defined, out);
            }
        }
        IrStmt::Try {
            body,
            excepts,
            else_body,
            finally_body,
        } => {
            for b in body.iter().chain(else_body).chain(finally_body) {
                record_all_calls_in_stmt(b, defined, out);
            }
            for ex in excepts {
                if let Some(m) = &ex.match_expr {
                    record_all_calls_in_expr(m, defined, out);
                }
                for b in &ex.body {
                    record_all_calls_in_stmt(b, defined, out);
                }
            }
        }
        IrStmt::Select { clauses } => {
            for c in clauses {
                if let Some(ch) = &c.ch {
                    record_all_calls_in_expr(ch, defined, out);
                }
                if let Some(v) = &c.value {
                    record_all_calls_in_expr(v, defined, out);
                }
                for b in &c.body {
                    record_all_calls_in_stmt(b, defined, out);
                }
            }
        }
        IrStmt::Asm { inputs, outputs, .. } => {
            for (_, e) in inputs.iter().chain(outputs) {
                record_all_calls_in_expr(e, defined, out);
            }
        }
        // Leaves and non-calling forms.
        IrStmt::Break
        | IrStmt::Continue
        | IrStmt::Label(_)
        | IrStmt::Goto(_)
        | IrStmt::Require(_)
        | IrStmt::RawText(_)
        | IrStmt::Die { .. }
        | IrStmt::Warn { .. }
        | IrStmt::Ext(_) => {}
    }
}


/// The `echo ARGS...` / `printf FMT ARGS...` statements that lower via
/// [`try_native_echo`] / [`try_native_printf`] — the other droppable
/// lastExit writers (the seq `(write, sh2.lastExit = 0, true)`). Same
/// carrier shape as the native let (the general
/// `IrStmt::Expr(Call("exec", …))` form).
fn is_native_echo_stmt(stmt: &IrStmt) -> bool {
    match stmt {
        IrStmt::Expr(IrExpr::Call { func, args, .. }) => {
            func == "exec"
                && matches!(
                    args.as_slice(),
                    [IrExpr::Str(n, _), IrExpr::Array(_)] if n == "echo" || n == "printf"
                )
        }
        _ => false,
    }
}

/// Mark DEAD every native `(( ))` statement whose lastExit write is not in
/// the live set (droppable) — only if its args actually parse natively
/// (the ternary only exists on the `try_native_let` path). Same for the
/// native `echo` statement (the emission-side dead variant re-checks the
/// sink/glob guards before dropping the write).
fn mark_lastexit_dead(stmts: &[IrStmt], live: &HashSet<usize>, dead: &mut HashMap<usize, bool>) {
    for stmt in stmts {
        if is_native_let_stmt(stmt) && !live.contains(&(stmt as *const IrStmt as usize)) {
            // the arith_forms Assign(Arith(IncDec)) shape is always
            // natively parseable (the transform only emits parsed ASTs)
            let native = match stmt {
                IrStmt::Exec { args, .. } | IrStmt::Expr(IrExpr::Call { args, .. }) => {
                    let native = match args.as_slice() {
                        [IrExpr::Str(_, _), IrExpr::Array(a)] => a.iter().all(|arg| match arg {
                            IrExpr::Str(sv, _) => native_arith_text(sv).is_some(),
                            _ => false,
                        }),
                        _ => false,
                    };
                    native
                }
                IrStmt::Assign { .. } => true,
                _ => false,
            };
            if native {
                dead.insert(stmt as *const IrStmt as usize, true);
            }
        }
        // the native echo/printf `(sh2.lastExit = 0)` write is droppable
        // when unread (the statement-level dead variant in `stmt_to_estree`
        // re-checks the sink/glob guards before dropping)
        if is_native_echo_stmt(stmt) && !live.contains(&(stmt as *const IrStmt as usize)) {
            dead.insert(stmt as *const IrStmt as usize, true);
        }
        // The native-decl `local`/`declare` path
        // (`try_native_local_decl_stmt`'s trailing `(sh2.lastExit = 0,
        // true)`): a statement-position pure-value decl whose names are
        // all local-lifted. When its status write is unread the trailing
        // seq is droppable (the polyfill's per-function `local s="$1"`
        // decls are exactly this shape). Only when the decl's args
        // actually parse (`declare_sources_dyn` — the dead twin would
        // refuse otherwise).
        if let IrStmt::Expr(IrExpr::Call { func, args, .. }) = stmt {
            if matches!(func.as_str(), "builtin" | "exec")
                && matches!(args.first(), Some(IrExpr::Str(n, _))
                    if matches!(n.as_str(), "local" | "declare" | "typeset"))
            {
                if !live.contains(&(stmt as *const IrStmt as usize))
                    && declare_sources_dyn(args).is_some()
                {
                    dead.insert(stmt as *const IrStmt as usize, true);
                }
            }
        }
        // A bare `[ ]`-test STATEMENT (`IrStmt::Expr(Call{func:"test"})`
        // — the `[ ]` lowering; the `[[ ]]` tag form carries the extra
        // Str arg) whose status write is unread: the native lowering's
        // `(sh2._g = t, sh2.lastExit = …, sh2._g)` seq collapses to the
        // bare boolean (the statement's only effect is the status — the
        // value is discarded). The scan already treats the test as a
        // writer (`ir_stmt_writes_lastexit`); a `$?` read anywhere before
        // the next writer keeps it live.
        if let IrStmt::Expr(IrExpr::Call { func, .. }) = stmt {
            if func == "test" && !live.contains(&(stmt as *const IrStmt as usize)) {
                dead.insert(stmt as *const IrStmt as usize, true);
            }
        }
        // Plan 4 for if-statements: an `if c; then ...; fi` with NO else
        // synthesizes `sh2.lastExit = 0` on the false path (bash: a false
        // condition with no else leaves `$?` = 0). When the if's status is
        // unread (its pointer is not in the live set — the backward scan
        // already treats the If as a writer, `ir_stmt_writes_lastexit`),
        // that write is dead and the if-lowering drops the else entirely.
        // Only EMPTY-else ifs synthesize the write (a non-empty else
        // carries its own status through its statements — no marking
        // needed).
        if let IrStmt::If { else_, .. } = stmt {
            if else_.is_empty() && !live.contains(&(stmt as *const IrStmt as usize)) {
                dead.insert(stmt as *const IrStmt as usize, true);
            }
        }
        match stmt {
            IrStmt::While { body, .. }
            | IrStmt::For { body, .. }
            | IrStmt::Block(body)
            | IrStmt::DoWhile { body, .. }
            | IrStmt::Subshell(body)
            | IrStmt::Background(body) => mark_lastexit_dead(body, live, dead),
            IrStmt::If {
                then,
                elsifs,
                else_,
                ..
            } => {
                mark_lastexit_dead(then, live, dead);
                for (_, arm) in elsifs {
                    mark_lastexit_dead(arm, live, dead);
                }
                mark_lastexit_dead(else_, live, dead);
            }
            IrStmt::Redirect { inner, .. } => mark_lastexit_dead(inner, live, dead),
            IrStmt::Function {
                body,
                named_blocks,
                ..
            } => {
                mark_lastexit_dead(body, live, dead);
                for (_, nb) in named_blocks {
                    mark_lastexit_dead(nb, live, dead);
                }
            }
            _ => {}
        }
    }
}

/// Plan 4 — compute the per-statement lastExit-write deadness map. Runs in
/// `shir_to_estree` before emission (the IR tree is immutable there). A
/// possible `set -e` guard-wraps every top-level statement (the guard
/// consumes the statement's value) — under errexit NO write is droppable
/// and the pass returns empty.
///
/// The PROGRAM-FINAL status IS observable in the ESTree backend: the
/// runner's `sh2._finish()` exits with `sh2.lastExit` (bash's exit code =
/// the last command's status; the corpus gate compares exit codes), so the
/// program-level `end_live` is TRUE — the final statement's write is live.
/// EXIT trap handlers run under REAL bash via spawnSync (they see bash's
/// own status, not sh2.lastExit), which is why `_finish` captures the code
/// BEFORE running the traps.
/// Backward-scan `stmts` and report whether a `$?`-reader chain reaches
/// the TOP of the block unshadowed — i.e. whether a lastExit write
/// PRECEDING the block (a `[ ]` condition's) would be observed from
/// within (an arm-internal reader before the first arm writer, or the
/// block's consumer when the block has no writer of its own — the
/// consumer then observes the cond's write as the block's final status).
/// Mirrors `scan_lastexit_liveness`'s read/write evolution exactly (the
/// same writer/reader predicates — the `live` inserts are irrelevant
/// here).
pub(crate) fn lastexit_scan_top_read(stmts: &[IrStmt], end_live: bool) -> bool {
    let mut read_pending = end_live;
    for stmt in stmts.iter().rev() {
        if ir_stmt_writes_lastexit(stmt) {
            read_pending = false;
        }
        if ir_stmt_reads_status(stmt) {
            read_pending = true;
        }
    }
    read_pending
}

/// Plan 4 for `[ ]`-test CONDITIONS (the if/while lowering — the
/// mimecroft hot path's `[ "$gv" -eq "$AIR" ]` per-block air test and
/// `[ "$rf_x" -lt "$MAP_W" ]` loop guards): a condition's status write
/// is DEAD iff no reader can observe it. Observation happens (a) from an
/// arm/body statement — a `$?` read before the first arm writer (the
/// arm's backward scan ends read-pending), or (b) from the statement's
/// own consumer — when the run arm has NO lastExit writer of its own,
/// the consumer observes the cond's write as the arm's final status
/// (the same scan with `end_live = self_live` — a writer-free arm passes
/// the consumer's read through to the top). Only If/While: DoWhile never
/// reaches the ESTree emitter (the renderer's catch-all refuses it); the
/// cond must be a direct `test` Call (a `!`/`&&`/`||`-wrapped cond keeps
/// the statused form — its value/status flow is chain-shaped).
/// A condition that is a pure chain of `[ ]`-style tests: an `And`/`Or`
/// tree whose leaves are all `test` calls (a test's VALUE equals its exit
/// status, so a native JS `&&`/`||` on the test values matches bash — the
/// reason the chain's status protocol is droppable when unread).
pub(crate) fn is_pure_test_chain(e: &IrExpr) -> bool {
    match e {
        IrExpr::Call { func, .. } => func == "test",
        IrExpr::BinOp { op, lhs, rhs } => {
            (matches!(op, BinOpKind::And | BinOpKind::Or)
                && is_pure_test_chain(lhs)
                && is_pure_test_chain(rhs))
                || (matches!(op, BinOpKind::Not) && is_pure_test_chain(lhs))
        }
        _ => false,
    }
}

fn compute_test_cond_deadness(stmts: &[IrStmt], live: &HashSet<usize>) -> HashMap<usize, bool> {
    fn mark(stmts: &[IrStmt], live: &HashSet<usize>, dead: &mut HashMap<usize, bool>) {
        for stmt in stmts {
            let self_live = live.contains(&(stmt as *const IrStmt as usize));
            match stmt {
                IrStmt::If {
                    cond,
                    then,
                    elsifs,
                    else_,
                    ..
                } => {
                    if is_pure_test_chain(cond) {
                        let mut top = lastexit_scan_top_read(then, self_live);
                        for (_, arm) in elsifs {
                            top |= lastexit_scan_top_read(arm, self_live);
                        }
                        top |= lastexit_scan_top_read(else_, self_live);
                        if !top {
                            dead.insert(stmt as *const IrStmt as usize, true);
                        }
                    }
                }
                IrStmt::While { cond, body, .. } => {
                    if is_pure_test_chain(cond) {
                        if !lastexit_scan_top_read(body, self_live) {
                            dead.insert(stmt as *const IrStmt as usize, true);
                        }
                    }
                }
                _ => {}
            }
            match stmt {
                IrStmt::While { body, .. }
                | IrStmt::For { body, .. }
                | IrStmt::Block(body)
                | IrStmt::DoWhile { body, .. }
                | IrStmt::Subshell(body)
                | IrStmt::Background(body) => mark(body, live, dead),
                IrStmt::If {
                    then,
                    elsifs,
                    else_,
                    ..
                } => {
                    mark(then, live, dead);
                    for (_, arm) in elsifs {
                        mark(arm, live, dead);
                    }
                    mark(else_, live, dead);
                }
                IrStmt::Redirect { inner, .. } => mark(inner, live, dead),
                IrStmt::Function {
                    body,
                    named_blocks,
                    ..
                } => {
                    mark(body, live, dead);
                    for (_, nb) in named_blocks {
                        mark(nb, live, dead);
                    }
                }
                _ => {}
            }
        }
    }
    let mut dead = HashMap::new();
    mark(stmts, live, &mut dead);
    dead
}

fn compute_lastexit_deadness(prog: &IrProgram, errexit: bool) -> HashMap<usize, bool> {
    let mut dead = HashMap::new();
    if errexit {
        // under a possible `set -e` no write is droppable (the guard
        // consumes the statement's value) — same for the test conds
        *TEST_COND_DEAD.lock().unwrap() = Some(HashMap::new());
        return dead;
    }
    let mut live: HashSet<usize> = HashSet::new();
    walk_lastexit_liveness(&prog.stmts, true, &mut live);
    mark_lastexit_dead(&prog.stmts, &live, &mut dead);
    *TEST_COND_DEAD.lock().unwrap() = Some(compute_test_cond_deadness(&prog.stmts, &live));
    dead
}

/// Loops (`IrStmt::While`, pointer-keyed) whose FINAL status write is dead
/// — no reader observes `$?` after the loop before the next write. Set per
/// compilation by `shir_to_estree` (a sibling of the Plan 4 liveness; the
/// same backward scan produces both). Under a possible `set -e` the map is
/// EMPTY (nothing dead — the guard consumes the status). The native while
/// lowering drops the per-iteration `bodyLast` tracking + trailing write
/// for these loops (a bare native `while (cond) { body }`).
static LOOP_STATUS_DEAD: Mutex<Option<HashMap<usize, bool>>> = Mutex::new(None);
/// Loop statement pointers provably executed at least once (sound
/// constant propagation + test-condition evaluation — see
/// collect_provably_running_loops). ShIR markup: also serialized as
/// `"runs": true` on the loop nodes (shir_json.rs), so every backend
/// consuming the A1 contract knows the body always runs.
static PROVABLY_RUNS: Mutex<Option<HashSet<usize>>> = Mutex::new(None);
// ── prove a loop runs at least once ──────────────────────────────
// Sound constant propagation over the statements BEFORE the loop, then
// evaluate a simple test condition. Anything unprovable → false
// (conservative — the emitter keeps its ran/last machinery).
fn const_value(expr: &IrExpr) -> Option<i128> {
    match expr {
        IrExpr::Int(n) => Some(*n as i128),
        IrExpr::Str(s, _) => s.trim().parse::<i128>().ok(),
        IrExpr::Arith(a) => arith_const(a),
        _ => None,
    }
}
fn arith_const(a: &ArithAst) -> Option<i128> {
    match a {
        ArithAst::Num(n) => Some(*n as i128),
        ArithAst::Bin { op, lhs, rhs } => {
            let l = arith_const(lhs)?;
            let r = arith_const(rhs)?;
            match op.as_str() {
                "+" => Some(l + r),
                "-" => Some(l - r),
                "*" => Some(l * r),
                "/" => (r != 0).then(|| l / r),
                "%" => (r != 0).then(|| l % r),
                _ => None,
            }
        }
        _ => None,
    }
}
fn test_operand(s: &str, vals: &HashMap<String, i128>) -> Option<i128> {
    let t = s.trim().trim_matches('"');
    if let Some(name) = t.strip_prefix('$') {
        vals.get(name).copied()
    } else if let Some(name) = t
        .strip_prefix("${")
        .and_then(|x| x.strip_suffix('}'))
    {
        vals.get(name).copied()
    } else {
        t.parse::<i128>().ok()
    }
}
fn eval_test_str(s: &str, vals: &HashMap<String, i128>) -> Option<bool> {
    const OPS: &[(&str, fn(i128, i128) -> bool)] = &[
        ("-lt", |a, b| a < b),
        ("-gt", |a, b| a > b),
        ("-le", |a, b| a <= b),
        ("-ge", |a, b| a >= b),
        ("-eq", |a, b| a == b),
        ("-ne", |a, b| a != b),
    ];
    for (op, f) in OPS {
        let needle = format!(" {op} ");
        if let Some(pos) = s.find(&needle) {
            let left = s[..pos].trim();
            let right = s[pos + needle.len()..].trim();
            let l = test_operand(left, vals)?;
            let r = test_operand(right, vals)?;
            return Some(f(l, r));
        }
    }
    None
}
fn loop_provably_runs_in(stmts: &[IrStmt], idx: usize) -> bool {
    let st = &stmts[idx];
    match st {
        IrStmt::DoWhile { .. } => true,
        IrStmt::For { iter, .. } => match iter {
            IrExpr::Array(items) => !items.is_empty(),
            IrExpr::Range { start, end } => start <= end,
            _ => false,
        },
        IrStmt::While { cond, .. } => {
            let mut vals: HashMap<String, i128> = HashMap::new();
            for st in &stmts[..idx] {
                match st {
                    IrStmt::Assign { targets, expr, .. }
                        if targets.len() == 1 && targets[0].indices.is_empty() =>
                    {
                        match const_value(expr) {
                            Some(n) => { vals.insert(targets[0].var.clone(), n); }
                            None => { vals.remove(&targets[0].var); }
                        }
                    }
                    IrStmt::While { .. }
                    | IrStmt::DoWhile { .. }
                    | IrStmt::For { .. }
                    | IrStmt::If { .. }
                    | IrStmt::Case { .. }
                    | IrStmt::Function { .. }
                    | IrStmt::Subshell(_)
                    | IrStmt::Background(_)
                    | IrStmt::Pipeline { .. }
                    | IrStmt::Block(_) => { vals.clear(); }
                    _ => {}
                }
            }
            match cond {
                IrExpr::Call { func, args, .. } if func == "test" => {
                    if let Some(IrExpr::Str(s, _)) = args.first() {
                        return eval_test_str(s, &vals).unwrap_or(false);
                    }
                    false
                }
                _ => false,
            }
        }
        _ => false,
    }
}
fn collect_provably_running_loops(stmts: &[IrStmt], out: &mut HashSet<usize>) {
    for (idx, st) in stmts.iter().enumerate() {
        if matches!(
            st,
            IrStmt::While { .. } | IrStmt::DoWhile { .. } | IrStmt::For { .. }
        ) && loop_provably_runs_in(stmts, idx)
        {
            out.insert(st as *const IrStmt as usize);
        }
        let body: Option<&Vec<IrStmt>> = match st {
            IrStmt::While { body, .. }
            | IrStmt::DoWhile { body, .. }
            | IrStmt::For { body, .. }
            | IrStmt::Block(body)
            | IrStmt::Subshell(body)
            | IrStmt::Background(body) => Some(body),
            IrStmt::If { then, elsifs, else_, .. } => {
                collect_provably_running_loops(then, out);
                for (_, b) in elsifs { collect_provably_running_loops(b, out); }
                collect_provably_running_loops(else_, out);
                None
            }
            _ => None,
        };
        if let Some(b) = body { collect_provably_running_loops(b, out); }
    }
}
pub(crate) fn set_provably_running_loops(stmts: &[IrStmt]) {
    let mut runs = HashSet::new();
    collect_provably_running_loops(stmts, &mut runs);
    *PROVABLY_RUNS.lock().unwrap() = Some(runs);
}
pub(crate) fn stmt_provably_runs(s: &IrStmt) -> bool {
    loop_provably_runs(s)
}
fn loop_provably_runs(stmt: &IrStmt) -> bool {
    PROVABLY_RUNS
        .lock()
        .unwrap()
        .as_ref()
        .map(|m| m.contains(&(stmt as *const IrStmt as usize)))
        .unwrap_or(false)
}

/// The FUNCTION-BODY loop-status twin of [`ARROW_BODY_DEAD`] (same
/// clone-pointer gap — the clone's loops consult this map during the
/// define-arrow construction). Computed from the clone's own liveness
/// alongside ARROW_BODY_DEAD; save/restored together with it.
static ARROW_BODY_LOOP_DEAD: Mutex<Option<HashMap<usize, bool>>> = Mutex::new(None);
fn loop_status_write_dead(stmt: &IrStmt) -> bool {
    // The active function-arrow construction's map wins (its pointers are
    // the exact statements being emitted); fall back to the global map
    // (original-tree pointers — loops/subshells outside arrows).
    if let Some(m) = ARROW_BODY_LOOP_DEAD.lock().unwrap().as_ref() {
        if let Some(&dead) = m.get(&(stmt as *const IrStmt as usize)) {
            return dead;
        }
    }
    LOOP_STATUS_DEAD
        .lock()
        .unwrap()
        .as_ref()
        .map(|m| {
            m.get(&(stmt as *const IrStmt as usize))
                .copied()
                .unwrap_or(false)
        })
        .unwrap_or(false)
}

