            cond: _,
            then,
            elsifs,
            else_,
        } => {
            let mut s1 = state.clone();
            for s in then {
                walk_stmt_ranges(s, &mut s1);
            }
            let mut s2 = state.clone();
            for (_, b) in elsifs {
                for s in b {
                    walk_stmt_ranges(s, &mut s2);
                }
            }
            for s in else_ {
                walk_stmt_ranges(s, &mut s2);
            }
