        | IrStmt::DoWhile { body, .. }
        | IrStmt::Block(body)
        | IrStmt::Function { body, .. }
        | IrStmt::Subshell(body)
        | IrStmt::Background(body) => {
            for b in body {
                collect_assigns(b, assigns);
            }
        }
