    // (the loop runs at most 4 times from 1, the last write overshoots
    // the bound by one step, and i=1 is reachable when it never runs)
    let r2 = ranges_of("i=1\nwhile [ $i -lt 5 ]; do i=$((i+1)); done");
    assert_eq!(r2.get("i"), Some(&(1, 5)));
